-- ============================================================
-- Script  : 010_export_logs.sql
-- Purpose : Create ExportLogs table to track PDF/Excel/CSV
--           exports generated by the system.
-- Target  : financia-dev (and all environments)
-- Run by  : DBA — manual execution required
-- Date    : 2026-05-09
-- ============================================================

-- ── ExportLogs ────────────────────────────────────────────────────────────────

CREATE TABLE [dbo].[ExportLogs]
(
    [ExportLogId]       BIGINT           IDENTITY(1,1)  NOT NULL,
    [AnalysisId]  UNIQUEIDENTIFIER               NOT NULL,
    [TenantId]          NVARCHAR(100)                  NOT NULL,
    [ExportedBy]        UNIQUEIDENTIFIER               NOT NULL,
    [Format]            NVARCHAR(20)                   NOT NULL,  -- PDF | Excel | CSV
    [SectionsIncluded]  NVARCHAR(MAX)                  NOT NULL,  -- JSON array of section keys
    [FileHashSha256]    NCHAR(64)                      NOT NULL,
    [IpAddress]         NVARCHAR(50)                   NULL,
    [ExportedAt]        DATETIME2                      NOT NULL
        CONSTRAINT [DF_ExportLogs_ExportedAt] DEFAULT (GETUTCDATE()),

    CONSTRAINT [PK_ExportLogs]
        PRIMARY KEY CLUSTERED ([ExportLogId] ASC),

    CONSTRAINT [CK_ExportLogs_Format]
        CHECK ([Format] IN ('PDF', 'Excel', 'CSV'))
);
GO

-- ── Indexes ───────────────────────────────────────────────────────────────────

CREATE NONCLUSTERED INDEX [IX_ExportLogs_TenantId_ExportedAt]
    ON [dbo].[ExportLogs] ([TenantId] ASC, [ExportedAt] DESC);
GO

CREATE NONCLUSTERED INDEX [IX_ExportLogs_AnalysisId]
    ON [dbo].[ExportLogs] ([AnalysisId] ASC);
GO
